import csv
from datetime import datetime

# 详细检查2024-03月份的订单
march_order_details = []
with open('orders.csv', 'r') as f:
    reader = csv.DictReader(f)
    for i, row in enumerate(reader, 2):  # 从第2行开始
        if row['date']:
            try:
                date_obj = datetime.strptime(row['date'], '%Y-%m-%d')
                if date_obj.strftime('%Y-%m') == '2024-03':
                    march_order_details.append({
                        'line': i,
                        'order_id': row['order_id'],
                        'amount': row['amount'],
                        'date': row['date']
                    })
            except ValueError:
                pass

print(f'2024-03月份原始订单详情:')
